22	  // 시즌 UI 요소
23	  private seasonText?: Phaser.GameObjects.Text;
24	  private prevSeasonReward: PrevSeasonReward | null = null;
25	
26	  // 보상수령 버튼 (create에서 1회 생성, updateRewardUI에서 상태 변경)
27	  private rewardBtnBg?: Phaser.GameObjects.Rectangle;
28	  private rewardBtnLabel?: Phaser.GameObjects.Text;
29	
30	  constructor() {
31	    super('LeaderboardScene');
32	  }
33	
34	  init() {
35	    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
36	    if (last) {
37	      this.selectedDifficulty = last;
38	    }
39	  }
40	
41	  preload() {
42	    if (!this.textures.exists('background2')) {
43	      this.load.image('background2', 'assets/backgrounds/background2.webp');
44	    }
45	    // 캐릭터 아이콘 (랭킹 표시용)
46	    CHARACTERS.forEach(char => {
47	      if (!this.textures.exists(char.imageKey)) {
48	        this.load.image(char.imageKey, char.imagePath);
49	      }
50	    });
51	  }
52	
53	  create() {
54	    super.create();
55	
56	    const W = this.scale.width;
57	    const H = this.scale.height;
58	    const cx = W / 2;
59	    const yOff = (H - 600) / 2;
60	
61	    // 배경 이미지 추가
62	    const background = this.add.image(cx, H / 2, 'background2');
63	    background.setDisplaySize(W, H);
64	
65	    // 타이틀
66	    this.add.text(cx, 40 + yOff, '🏆 랭킹보드 🏆', {
67	      fontSize: '28px',
68	      color: '#fff',
69	      fontStyle: 'bold',
70	      stroke: '#000',
71	      strokeThickness: 5,
72	      padding: { top: 6 },
73	    }).setOrigin(0.5);
74	
75	    // 시즌 월 표시 (데이터 로드 후 갱신)
76	    this.seasonText = this.add.text(cx, 70 + yOff, '', {
77	      fontSize: '13px',
78	      color: '#aaddff',
79	      stroke: '#000',
80	      strokeThickness: 3,
81	    }).setOrigin(0.5);
82	
83	    // 난이도 선택 버튼들
84	    this.createDifficultyButtons(cx, yOff);
85	
86	    // 랭킹 표시 영역 (초기 로딩)
87	    this.loadingText = this.add.text(cx, H / 2, '로딩 중...', {
88	      fontSize: '20px',
89	      color: '#fff',
90	      stroke: '#000',
91	      strokeThickness: 3
92	    }).setOrigin(0.5);
93	
94	    // 보상수령 버튼 (하단 왼쪽, 뒤로가기와 나란히)
95	    const rbY = H - 40;
96	    this.rewardBtnBg = this.add.rectangle(cx - 80, rbY, 150, 40, 0x555555, 1);
97	    this.rewardBtnBg.setStrokeStyle(3, 0x333333);
98	    this.rewardBtnLabel = this.add.text(cx - 80, rbY, '보상수령', {
99	      fontSize: '18px',
100	      color: '#999999',
101	      fontStyle: 'bold',
102	      stroke: '#000',
103	      strokeThickness: 4,
104	    }).setOrigin(0.5);
105	
106	    // 뒤로가기 버튼 (하단 오른쪽)
107	    this.createBackButton(cx + 80, H - 40);
108	
109	    // 초기 데이터 로드
110	    this.loadLeaderboard();
111	  }
112	
113	  private createDifficultyButtons(cx: number, yOff: number) {
114	    this.difficultyButtons.forEach(btn => btn.destroy());
115	    this.difficultyButtons.clear();
116	
117	    const difficulties: Difficulty[] = [
118	      DifficultyEnum.NORMAL,
119	      DifficultyEnum.HARD,
120	      DifficultyEnum.EXTREME,
121	      DifficultyEnum.PHYSICAL
122	    ];
123	
124	    const buttonWidth = 70;
125	    const spacing = 85;
126	    const startX = cx - (spacing * 1.5);
127	    const y = 108 + yOff;
128	
129	    difficulties.forEach((difficulty, index) => {
130	      const x = startX + (index * spacing);
131	      const isSelected = difficulty === this.selectedDifficulty;
132	
133	      const button = this.add.rectangle(
134	        x,
135	        y,
136	        buttonWidth,
137	        35,
138	        isSelected ? 0xffff99 : 0xffffff,
139	        1
140	      );
141	      button.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
142	
143	      this.add.text(x, y, difficulty, {
144	        fontSize: '12px',
145	        color: '#000',
146	        fontStyle: 'bold'
147	      }).setOrigin(0.5);
148	
149	      this.difficultyButtons.set(difficulty, button);
150	      button.setInteractive({ useHandCursor: true });
151	
152	      button.on('pointerover', () => {
153	        if (difficulty !== this.selectedDifficulty) {
154	          button.setFillStyle(0xffffcc);
155	        }
156	      });
157	
158	      button.on('pointerout', () => {
159	        if (difficulty !== this.selectedDifficulty) {
160	          button.setFillStyle(0xffffff);
161	        }
162	      });
163	
164	      button.on('pointerdown', () => {
165	        this.selectDifficulty(difficulty);
166	      });
167	    });
168	  }
169	
170	  private selectDifficulty(difficulty: Difficulty) {
171	    // 같은 난이도면 무시
172	    if (this.selectedDifficulty === difficulty) {
173	      return;
174	    }
175	
176	    this.selectedDifficulty = difficulty;
177	
178	    // 모든 버튼 스타일 재설정
179	    this.difficultyButtons.forEach((btn, diff) => {
180	      const isSelected = diff === difficulty;
181	      btn.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
182	      btn.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
183	    });
184	
185	    // 새로운 난이도 데이터 로드
186	    this.loadLeaderboard();
187	  }
188	
189	  private async loadLeaderboard() {
190	    // 요청 ID 증가 (새로운 요청 시작)
191	    this.currentRequestId++;
192	    const requestId = this.currentRequestId;
193	
194	    // 기존 랭킹 텍스트 제거
195	    this.leaderboardTexts.forEach(text => text.destroy());
196	    this.leaderboardTexts = [];
197	    this.prevSeasonReward = null;
198	
199	    if (this.errorText) {
200	      this.errorText.destroy();
201	      this.errorText = undefined;
202	    }
203	
204	    // 로딩 표시
205	    if (!this.loadingText) {
206	      this.loadingText = this.add.text(this.scale.width / 2, this.scale.height / 2, '로딩 중...', {
207	        fontSize: '20px',
208	        color: '#fff',
209	        stroke: '#000',
210	        strokeThickness: 3
211	      }).setOrigin(0.5);
212	    } else {
213	      this.loadingText.setVisible(true);
214	    }
215	
216	    try {
217	      const response = await getLeaderboard(this.selectedDifficulty, 10);
218	
219	      // 응답이 도착했을 때 최신 요청인지 확인
220	      if (requestId !== this.currentRequestId) {
221	        // 이미 새로운 요청이 시작됨 - 이 응답은 무시
222	        return;
223	      }
224	
225	      this.leaderboardData = response.leaderboard;
226	
227	      // 시즌 텍스트 갱신
228	      if (this.seasonText && response.yearMonth) {
229	        const [y, m] = response.yearMonth.split('-');
230	        const daysLeft = this.calcDaysUntilMonthEnd();
231	        this.seasonText.setText(`${y}년 ${parseInt(m)}월 시즌  |  시즌 종료까지 D-${daysLeft}`);
232	      }
233	
234	      // 직전 달 보상 상태 결정 (localStorage 캐시 우선)
235	      if (response.yearMonth) {
236	        const [y, m] = response.yearMonth.split('-').map(Number) as [number, number];
237	        const prevDate = new Date(Date.UTC(y, m - 2, 1));
238	        const prevYM = `${prevDate.getUTCFullYear()}-${String(prevDate.getUTCMonth() + 1).padStart(2, '0')}`;
239	        const cached = getCachedClaimAmount(prevYM, this.selectedDifficulty);
240	        if (cached !== null) {
241	          // localStorage 캐시 히트 → 서버 응답의 prevSeasonReward 무시하고 캐시 사용
242	          this.prevSeasonReward = {
243	            yearMonth: prevYM,
244	            rank: response.prevSeasonReward?.rank ?? null,
245	            skorAwarded: cached,
246	            alreadyClaimed: true,
247	          };
248	        } else {
249	          this.prevSeasonReward = response.prevSeasonReward;
250	        }
251	      } else {
252	        this.prevSeasonReward = null;
253	      }
254	
255	      if (this.loadingText) {
256	        this.loadingText.setVisible(false);
257	      }
258	
259	      this.displayLeaderboard();
260	      this.updateRewardUI();
261	    } catch (error) {
262	      // 에러가 발생했을 때도 최신 요청인지 확인
263	      if (requestId !== this.currentRequestId) {
264	        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
265	        return;
266	      }
267	
268	      console.error('Failed to load leaderboard:', error);
269	
270	      if (this.loadingText) {
271	        this.loadingText.setVisible(false);
272	      }
273	
274	      this.errorText = this.add.text(this.scale.width / 2, this.scale.height / 2, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
275	        fontSize: '16px',
276	        color: '#ff6666',
277	        stroke: '#000',
278	        strokeThickness: 3,
279	        align: 'center'
280	      }).setOrigin(0.5);
281	    }
282	  }
283	
284	  private displayLeaderboard() {
285	    const W = this.scale.width;
286	    const yOff = (this.scale.height - 600) / 2;
287	    const startY = 130 + yOff;
288	    const ROW_H = 38;
289	    const PAD = 48;
290	    const ROW_W = W - PAD * 2;
291	    const LEFT = PAD;
292	    const CX = W / 2;
293	
294	    // 컬럼 x 좌표 (모두 W 기준 비율 계산)
295	    // [순위 50px] [아이콘 44px] [← 이름 중앙 정렬 →] [점수 110px]
296	    const COL_RANK       = LEFT + 40;
297	    const COL_ICON       = LEFT + 72;
298	    const ICON_R         = LEFT + 89;
299	    const SCORE_L        = LEFT + ROW_W - 110;
300	    const COL_NAME       = (ICON_R + SCORE_L) / 2;
301	    const COL_SCORE      = LEFT + ROW_W - 6;
302	
303	    // ── 헤더 ────────────────────────────────────────────
304	    const headerY = startY + 16;
305	    const headerStyle = {
306	      fontSize: '13px',
307	      color: '#aaddff',
308	      fontStyle: 'bold',
309	      stroke: '#000',
310	      strokeThickness: 3,
311	    };
312	    this.leaderboardTexts.push(
313	      this.add.text(COL_RANK, headerY, '순위', headerStyle).setOrigin(1, 0.5),
314	      this.add.text(COL_NAME, headerY, '이름', headerStyle).setOrigin(0.5, 0.5),
315	      this.add.text(COL_SCORE, headerY, '점수', headerStyle).setOrigin(1, 0.5),
316	    );
317	    const divider = this.add.rectangle(CX, headerY + 11, ROW_W, 1, 0xaaddff, 0.5);
318	    this.leaderboardTexts.push(divider);
319	
320	    // ── 데이터 없음 ──────────────────────────────────────
321	    if (this.leaderboardData.length === 0) {
322	      const noDataText = this.add.text(
323	        CX, startY + 80,
324	        '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!',
325	        { fontSize: '18px', color: '#ccc', stroke: '#000', strokeThickness: 3, align: 'center' }
326	      ).setOrigin(0.5);
327	      this.leaderboardTexts.push(noDataText);
328	      return;
329	    }
330	
331	    // ── 각 행 ────────────────────────────────────────────
332	    this.leaderboardData.forEach((entry, index) => {
333	      const rowY = startY + 38 + index * ROW_H;
334	      const cy = rowY + ROW_H / 2;
335	
336	      // 행 배경
337	      const bgColor =
338	        entry.rank === 1 ? 0x4a3a00 :
339	        entry.rank === 2 ? 0x2a2a35 :
340	        entry.rank === 3 ? 0x3a2010 :
341	        index % 2 === 0  ? 0x0a0a18 : 0x121220;
342	      const bgAlpha = entry.rank <= 3 ? 0.85 : 0.55;
343	      const bg = this.add.rectangle(CX, cy, ROW_W, ROW_H - 2, bgColor, bgAlpha);
344	      this.leaderboardTexts.push(bg);
345	
346	      // 상위 3위 왼쪽 테두리 강조
347	      if (entry.rank <= 3) {
348	        const accentColor = entry.rank === 1 ? 0xFFD700 : entry.rank === 2 ? 0xC0C0C0 : 0xCD7F32;
349	        const accent = this.add.rectangle(LEFT + 1, cy, 3, ROW_H - 2, accentColor, 1);
350	        this.leaderboardTexts.push(accent);
351	      }
352	
353	      // 순위 색상
354	      const rankColor =
355	        entry.rank === 1 ? '#FFD700' :
356	        entry.rank === 2 ? '#C0C0C0' :
357	        entry.rank === 3 ? '#CD7F32' : '#aaaaaa';
358	
359	      // 순위 (숫자만)
360	      this.leaderboardTexts.push(
361	        this.add.text(COL_RANK, cy, `${entry.rank}`, {
362	          fontSize: '15px',
363	          color: rankColor,
364	          fontStyle: 'bold',
365	          stroke: '#000',
366	          strokeThickness: 3,
367	        }).setOrigin(1, 0.5)
368	      );
369	
370	      // 캐릭터 아이콘
371	      const charDef = CHARACTERS.find(c => c.id === (entry.characterType ?? 'chibi')) ?? CHARACTERS[0];
372	      this.leaderboardTexts.push(
373	        this.add.image(COL_ICON, cy, charDef.imageKey).setDisplaySize(30, 30).setOrigin(0.5)
374	      );
375	
376	      // 이름
377	      this.leaderboardTexts.push(
378	        this.add.text(COL_NAME, cy, entry.userName, {
379	          fontSize: '15px',
380	          color: entry.rank <= 3 ? '#ffffff' : '#dddddd',
381	          fontFamily: 'monospace',
382	          fontStyle: 'bold',
383	          stroke: '#000',
384	          strokeThickness: 3,
385	        }).setOrigin(0.5, 0.5)
386	      );
387	
388	      // 점수
389	      this.leaderboardTexts.push(
390	        this.add.text(COL_SCORE, cy, entry.score.toLocaleString(), {
391	          fontSize: '15px',
392	          color: entry.rank <= 3 ? rankColor : '#ffffff',
393	          fontFamily: 'monospace',
394	          fontStyle: 'bold',
395	          stroke: '#000',
396	          strokeThickness: 3,
397	        }).setOrigin(1, 0.5)
398	      );
399	    });
400	  }
401	
402	  /** 이번 달 말일까지 남은 일수 */
403	  private calcDaysUntilMonthEnd(): number {
404	    const now = new Date();
405	    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
406	    const diff = lastDay.getTime() - now.getTime();
407	    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
408	  }
409	
410	  /** 보상수령 버튼 상태 갱신 */
411	  private updateRewardUI() {
412	    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
413	
414	    const btn = this.rewardBtnBg;
415	    const label = this.rewardBtnLabel;
416	    const reward = this.prevSeasonReward;
417	
418	    btn.removeAllListeners();
419	    btn.disableInteractive();
420	
421	    if (!reward || reward.rank === null || reward.skorAwarded === 0) {
422	      // 비활성: 기록 없음 또는 100위 밖
423	      btn.setFillStyle(0x555555).setStrokeStyle(3, 0x333333);
424	      label.setText('보상수령').setColor('#999999');
425	
426	    } else if (reward.alreadyClaimed) {
427	      // 비활성: 수령 완료 (초록)
428	      btn.setFillStyle(0x336633).setStrokeStyle(3, 0x224422);
429	      label.setText('수령완료').setColor('#88ff88');
430	
431	    } else {
432	      // 활성: 수령 가능 (노란색)
433	      btn.setFillStyle(0xffcc00).setStrokeStyle(3, 0xaa8800);
434	      label.setText('보상수령').setColor('#000000');
435	      btn.setInteractive({ useHandCursor: true });
436	      btn.on('pointerover', () => btn.setFillStyle(0xffe566));
437	      btn.on('pointerout', () => btn.setFillStyle(0xffcc00));
438	      btn.on('pointerdown', () => this.handleClaimReward());
439	    }
440	  }
441	
442	  /** 보상받기 버튼 클릭 처리 */
443	  private async handleClaimReward() {
444	    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
445	
446	    // 처리 중 표시 (중복 클릭 방지)
447	    this.rewardBtnBg.disableInteractive();
448	    this.rewardBtnLabel.setText('처리중...').setColor('#aaaaaa');
449	
450	    try {
451	      const result = await claimSeasonReward(this.selectedDifficulty);
452	
453	      if (result.success && (result.skorAwarded ?? 0) > 0) {
454	        if (this.prevSeasonReward) {
455	          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
456	        }
457	        this.updateRewardUI();
458	
459	        // 획득 플래시 연출
460	        const flashText = this.add.text(
461	          this.scale.width / 2, this.scale.height / 2 - 60,
462	          `+${result.skorAwarded} SKOR 획득!`, {
463	            fontSize: '24px',
464	            color: '#ffcc00',
465	            fontStyle: 'bold',
466	            stroke: '#000',
467	            strokeThickness: 5,
468	          }
469	        ).setOrigin(0.5);
470	
471	        this.tweens.add({
472	          targets: flashText,
473	          alpha: { from: 1, to: 0 },
474	          y: flashText.y - 40,
475	          duration: 1500,
476	          ease: 'Cubic.easeOut',
477	          onComplete: () => flashText.destroy(),
478	        });
479	      } else {
480	        if (this.prevSeasonReward && result.alreadyClaimed) {
481	          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
482	        }
483	        this.updateRewardUI();
484	      }
485	    } catch {
486	      // 실패 시 원래 상태로 복구
487	      this.updateRewardUI();
488	    }
489	  }
490	
491	  private createBackButton(cx: number, y: number) {
492	    const button = this.add.rectangle(cx, y, 150, 40, 0xffffff, 1);
493	    button.setStrokeStyle(3, 0x000000);
494	
495	    const text = this.add.text(cx, y, '← 뒤로가기', {
496	      fontSize: '18px',
497	      color: '#000',
498	      fontStyle: 'bold'
499	    }).setOrigin(0.5);
500	
501	    button.setInteractive({ useHandCursor: true });
502	
503	    const elements = [button, text];
504	    elements.forEach(element => {
505	      element.on('pointerover', () => {
506	        button.setFillStyle(0xffff99);
507	      });
508	
509	      element.on('pointerout', () => {
510	        button.setFillStyle(0xffffff);
511	      });
512	
513	      element.on('pointerdown', () => {
514	        this.scene.start('ModeSelectScene');
515	      });
516	    });
517	  }
518	}
