/** EXTREME 선택 시 캐릭터 필터 드롭다운 버튼 렌더 */
private updateCharFilterRow() {
  this.charFilterObjects.forEach(o => o.destroy());
  this.charFilterObjects = [];

  if (this.selectedDifficulty !== DifficultyEnum.EXTREME) return;

  const W = this.scale.width;
  const yOff = (this.scale.height - 600) / 2;
  const cy = 145 + yOff;
  const cx = W / 2;

  const selectedName = this.selectedCharFilter === null
    ? '전체'
    : (CHARACTERS.find(c => c.id === this.selectedCharFilter)?.name ?? this.selectedCharFilter);
  const label = `👤 ${selectedName}  ▼`;

  const btn = this.add.rectangle(cx, cy, 180, 28, 0x1a1a3a, 1);
  btn.setStrokeStyle(2, 0x5566aa);
  const txt = this.add.text(cx, cy, label, {
    fontSize: '12px', color: '#aaccff', fontStyle: 'bold',
  }).setOrigin(0.5);

  btn.setInteractive({ useHandCursor: true });
  btn.on('pointerover', () => btn.setFillStyle(0x2a2a5a));
  btn.on('pointerout',  () => btn.setFillStyle(0x1a1a3a));
  btn.on('pointerdown', () => this.showCharSelectOverlay());

  this.charFilterObjects.push(btn, txt);
}

/** 캐릭터 선택 오버레이 표시 */
private showCharSelectOverlay() {
  if (this.charOverlayObjects.length > 0) return;

  const W = this.scale.width;
  const H = this.scale.height;
  const cx = W / 2;
  const yOff = (H - 600) / 2;
  const DEPTH = 500;

  // 반투명 배경
  const bg = this.add.rectangle(cx, H / 2, W, H, 0x000000, 0.88).setDepth(DEPTH).setInteractive();
  this.charOverlayObjects.push(bg);

  // 타이틀
  const title = this.add.text(cx, 38 + yOff, '캐릭터 선택', {
    fontSize: '20px', color: '#ffffff', fontStyle: 'bold',
    stroke: '#000', strokeThickness: 4,
  }).setOrigin(0.5).setDepth(DEPTH + 1);
  this.charOverlayObjects.push(title);

  // "전체" 버튼
  const allSel = this.selectedCharFilter === null;
  const allBg = this.add.rectangle(cx, 70 + yOff, 160, 30,
    allSel ? 0x334488 : 0x222233, 1).setDepth(DEPTH + 1);
  allBg.setStrokeStyle(2, allSel ? 0xaaccff : 0x444466);
  const allTxt = this.add.text(cx, 70 + yOff, '전체 랭킹', {
    fontSize: '13px', color: allSel ? '#ffffff' : '#8899bb', fontStyle: 'bold',
  }).setOrigin(0.5).setDepth(DEPTH + 2);
  allBg.setInteractive({ useHandCursor: true });
  allBg.on('pointerdown', () => {
    this.hideCharSelectOverlay();
    if (this.selectedCharFilter !== null) {
      this.selectedCharFilter = null;
      this.loadLeaderboard();
    }
  });
  this.charOverlayObjects.push(allBg, allTxt);

  // 캐릭터 그리드 (4열)
  const COLS = 4;
  const CELL_W = 88, CELL_H = 72;
  const gridLeft = (W - COLS * CELL_W) / 2;
  const gridTop = 100 + yOff;

  CHARACTERS.forEach((char, i) => {
    const col = i % COLS;
    const row = Math.floor(i / COLS);
    const cx2 = gridLeft + col * CELL_W + CELL_W / 2;
    const cy2 = gridTop + row * CELL_H + CELL_H / 2;

    const isSel = this.selectedCharFilter === char.id;
    const cellBg = this.add.rectangle(cx2, cy2, CELL_W - 4, CELL_H - 4,
      isSel ? 0x334488 : 0x111122, isSel ? 1 : 0.7).setDepth(DEPTH + 1);
    cellBg.setStrokeStyle(isSel ? 2 : 1, isSel ? 0xaaccff : 0x333355);

    const icon = this.add.image(cx2, cy2 - 10, char.imageKey)
      .setDisplaySize(38, 38).setOrigin(0.5).setDepth(DEPTH + 2);
    if (!isSel) icon.setTint(0xaaaaaa);

    const nameTxt = this.add.text(cx2, cy2 + 22, char.name, {
      fontSize: '9px', color: isSel ? '#ffffff' : '#888899',
    }).setOrigin(0.5).setDepth(DEPTH + 2);

    const gradeColor: Record<string, string> = { '등급외': '#aaaaaa', R: '#66aaff', SR: '#cc88ff', UR: '#ffdd44' };
    const gradeDot = this.add.circle(cx2 + 17, cy2 - 24, 4,
      parseInt((gradeColor[char.grade] ?? '#aaaaaa').replace('#', ''), 16))
      .setDepth(DEPTH + 2);

    cellBg.setInteractive({ useHandCursor: true });
    cellBg.on('pointerover', () => { if (!isSel) cellBg.setFillStyle(0x1e2244); });
    cellBg.on('pointerout',  () => { if (!isSel) cellBg.setFillStyle(0x111122); });
    cellBg.on('pointerdown', () => {
      this.hideCharSelectOverlay();
      if (this.selectedCharFilter !== char.id) {
        this.selectedCharFilter = char.id;
        this.loadLeaderboard();
      }
    });

    this.charOverlayObjects.push(cellBg, icon, nameTxt, gradeDot);
  });

  // 닫기 버튼
  const closeY = gridTop + Math.ceil(CHARACTERS.length / COLS) * CELL_H + 16;
  const closeBg = this.add.rectangle(cx, closeY, 100, 30, 0x333333, 1)
    .setDepth(DEPTH + 1).setStrokeStyle(2, 0x666666);
  const closeTxt = this.add.text(cx, closeY, '✕ 닫기', {
    fontSize: '13px', color: '#cccccc', fontStyle: 'bold',
  }).setOrigin(0.5).setDepth(DEPTH + 2);
  closeBg.setInteractive({ useHandCursor: true });
  closeBg.on('pointerdown', () => this.hideCharSelectOverlay());
  this.charOverlayObjects.push(closeBg, closeTxt);
}

/** 캐릭터 선택 오버레이 숨김 */
private hideCharSelectOverlay() {
  this.charOverlayObjects.forEach(o => o.destroy());
  this.charOverlayObjects = [];
  // 버튼 레이블 갱신
  this.updateCharFilterRow();
}

