503	        fontSize: '9px', color: isSel ? '#ffffff' : '#888899',
504	      }).setOrigin(0.5).setDepth(DEPTH + 2);
505	
506	      const gradeColor: Record<string, string> = { '등급외': '#aaaaaa', R: '#66aaff', SR: '#cc88ff', UR: '#ffdd44' };
507	      const gradeDot = this.add.circle(cx2 + 17, cy2 - 24, 4,
508	        parseInt((gradeColor[char.grade] ?? '#aaaaaa').replace('#', ''), 16))
509	        .setDepth(DEPTH + 2);
510	
511	      cellBg.setInteractive({ useHandCursor: true });
512	      cellBg.on('pointerover', () => { if (!isSel) cellBg.setFillStyle(0x1e2244); });
513	      cellBg.on('pointerout',  () => { if (!isSel) cellBg.setFillStyle(0x111122); });
514	      cellBg.on('pointerdown', () => {
515	        this.hideCharSelectOverlay();
516	        if (this.selectedCharFilter !== char.id) {
517	          this.selectedCharFilter = char.id;
518	          this.loadLeaderboard();
519	        }
520	      });
521	
522	      this.charOverlayObjects.push(cellBg, icon, nameTxt, gradeDot);
523	    });
524	
525	    // 닫기 버튼
526	    const closeY = gridTop + Math.ceil(CHARACTERS.length / COLS) * CELL_H + 16;
527	    const closeBg = this.add.rectangle(cx, closeY, 100, 30, 0x333333, 1)
528	      .setDepth(DEPTH + 1).setStrokeStyle(2, 0x666666);
529	    const closeTxt = this.add.text(cx, closeY, '✕ 닫기', {
530	      fontSize: '13px', color: '#cccccc', fontStyle: 'bold',
531	    }).setOrigin(0.5).setDepth(DEPTH + 2);
532	    closeBg.setInteractive({ useHandCursor: true });
533	    closeBg.on('pointerdown', () => this.hideCharSelectOverlay());
534	    this.charOverlayObjects.push(closeBg, closeTxt);
535	  }
536	
537	  /** 캐릭터 선택 오버레이 숨김 */
538	  private hideCharSelectOverlay() {
539	    this.charOverlayObjects.forEach(o => o.destroy());
540	    this.charOverlayObjects = [];
541	    // 버튼 레이블 갱신
542	    this.updateCharFilterRow();
543	  }
544	
545	  /** 이번 달 말일까지 남은 일수 */
546	  private calcDaysUntilMonthEnd(): number {
547	    const now = new Date();
548	    const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
549	    const diff = lastDay.getTime() - now.getTime();
550	    return Math.max(0, Math.ceil(diff / (1000 * 60 * 60 * 24)));
551	  }
552	
553	  /** 보상수령 버튼 상태 갱신 */
554	  private updateRewardUI() {
555	    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
556	
557	    const btn = this.rewardBtnBg;
558	    const label = this.rewardBtnLabel;
559	
560	    // 캐릭터 필터 활성 시 보상 버튼 비활성 (캐릭터별 순위에서 보상은 무의미)
561	    if (this.selectedCharFilter !== null) {
562	      btn.setFillStyle(0x555555).setStrokeStyle(3, 0x333333);
563	      btn.disableInteractive();
564	      btn.removeAllListeners();
565	      label.setText('보상수령').setColor('#999999');
566	      return;
567	    }
568	
569	    const reward = this.prevSeasonReward;
570	
571	    btn.removeAllListeners();
572	    btn.disableInteractive();
573	
574	    if (!reward || reward.rank === null || reward.skorAwarded === 0) {
575	      // 비활성: 기록 없음 또는 100위 밖
576	      btn.setFillStyle(0x555555).setStrokeStyle(3, 0x333333);
577	      label.setText('보상수령').setColor('#999999');
578	
579	    } else if (reward.alreadyClaimed) {
580	      // 비활성: 수령 완료 (초록)
581	      btn.setFillStyle(0x336633).setStrokeStyle(3, 0x224422);
582	      label.setText('수령완료').setColor('#88ff88');
583	
584	    } else {
585	      // 활성: 수령 가능 (노란색)
586	      btn.setFillStyle(0xffcc00).setStrokeStyle(3, 0xaa8800);
587	      label.setText('보상수령').setColor('#000000');
588	      btn.setInteractive({ useHandCursor: true });
589	      btn.on('pointerover', () => btn.setFillStyle(0xffe566));
590	      btn.on('pointerout', () => btn.setFillStyle(0xffcc00));
591	      btn.on('pointerdown', () => this.handleClaimReward());
592	    }
593	  }
594	
595	  /** 보상받기 버튼 클릭 처리 */
596	  private async handleClaimReward() {
597	    if (!this.rewardBtnBg || !this.rewardBtnLabel) return;
598	
599	    // 처리 중 표시 (중복 클릭 방지)
600	    this.rewardBtnBg.disableInteractive();
601	    this.rewardBtnLabel.setText('처리중...').setColor('#aaaaaa');
602	
603	    try {
604	      const result = await claimSeasonReward(this.selectedDifficulty);
605	
606	      if (result.success && (result.skorAwarded ?? 0) > 0) {
607	        if (this.prevSeasonReward) {
608	          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
609	        }
610	        this.updateRewardUI();
611	
612	        // 획득 플래시 연출
613	        const flashText = this.add.text(
614	          this.scale.width / 2, this.scale.height / 2 - 60,
615	          `+${result.skorAwarded} SKOR 획득!`, {
616	            fontSize: '24px',
617	            color: '#ffcc00',
618	            fontStyle: 'bold',
619	            stroke: '#000',
620	            strokeThickness: 5,
621	          }
622	        ).setOrigin(0.5);
623	
624	        this.tweens.add({
625	          targets: flashText,
626	          alpha: { from: 1, to: 0 },
627	          y: flashText.y - 40,
628	          duration: 1500,
629	          ease: 'Cubic.easeOut',
630	          onComplete: () => flashText.destroy(),
631	        });
632	      } else {
633	        if (this.prevSeasonReward && result.alreadyClaimed) {
634	          this.prevSeasonReward = { ...this.prevSeasonReward, alreadyClaimed: true };
635	        }
636	        this.updateRewardUI();
637	      }
638	    } catch {
639	      // 실패 시 원래 상태로 복구
640	      this.updateRewardUI();
641	    }
642	  }
643	
644	  private createBackButton(cx: number, y: number) {
645	    const button = this.add.rectangle(cx, y, 150, 40, 0xffffff, 1);
646	    button.setStrokeStyle(3, 0x000000);
647	
648	    const text = this.add.text(cx, y, '← 뒤로가기', {
649	      fontSize: '18px',
650	      color: '#000',
651	      fontStyle: 'bold'
652	    }).setOrigin(0.5);
653	
654	    button.setInteractive({ useHandCursor: true });
655	
656	    const elements = [button, text];
657	    elements.forEach(element => {
658	      element.on('pointerover', () => {
659	        button.setFillStyle(0xffff99);
660	      });
661	
662	      element.on('pointerout', () => {
663	        button.setFillStyle(0xffffff);
664	      });
