169	// ── 시즌 보상 수령 캐시 (localStorage) ──────────────────────────────────
170	// 수령 완료된 시즌/난이도는 localStorage에 캐시해 불필요한 서버 조회 방지
171	// 보안: djb2 서명으로 변조 방지 (실제 이중 수령은 서버 UNIQUE 제약이 방어)
172	
173	const _CLAIMS_KEY = 'seasonRewardClaims';
174	const _CLAIMS_SIG_KEY = 'seasonRewardClaimsSig';
175	const _CLAIMS_SALT = 'ddong-reward-\u0076\u0031';
176	
177	function _djb2(str: string): string {
178	  let h = 5381;
179	  for (let i = 0; i < str.length; i++) {
180	    h = ((h << 5) + h) ^ str.charCodeAt(i);
181	    h = h >>> 0;
182	  }
183	  return h.toString(36);
184	}
185	
186	function _signClaims(claims: Record<string, number>): string {
187	  const str = Object.entries(claims)
188	    .sort(([a], [b]) => a.localeCompare(b))
189	    .map(([k, v]) => `${k}:${v}`)
190	    .join(',') + _CLAIMS_SALT;
191	  return _djb2(str);
192	}
193	
194	/** 현재 달 + 직전 달 외의 오래된 캐시 항목 제거 */
195	function _pruneOldClaims(claims: Record<string, number>): Record<string, number> {
196	  const now = new Date();
197	  const cur = getCurrentYearMonth();
198	  const prevDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
199	  const prev = `${prevDate.getUTCFullYear()}-${String(prevDate.getUTCMonth() + 1).padStart(2, '0')}`;
200	  const keep = new Set([cur, prev]);
201	  return Object.fromEntries(
202	    Object.entries(claims).filter(([k]) => keep.has(k.slice(0, 7)))
203	  );
204	}
205	
206	function _loadClaimedCache(): Record<string, number> {
207	  try {
208	    const raw = localStorage.getItem(_CLAIMS_KEY);
209	    const sig = localStorage.getItem(_CLAIMS_SIG_KEY);
210	    if (!raw) return {};
211	    const parsed = JSON.parse(raw) as Record<string, number>;
212	    if (sig && sig !== _signClaims(parsed)) {
213	      // 서명 불일치 → 변조로 판단, 초기화
214	      localStorage.removeItem(_CLAIMS_KEY);
215	      localStorage.removeItem(_CLAIMS_SIG_KEY);
216	      return {};
217	    }
218	    return parsed;
219	  } catch {
220	    return {};
221	  }
222	}
223	
224	function _saveClaimedCache(claims: Record<string, number>): void {
225	  const pruned = _pruneOldClaims(claims);
226	  localStorage.setItem(_CLAIMS_KEY, JSON.stringify(pruned));
227	  localStorage.setItem(_CLAIMS_SIG_KEY, _signClaims(pruned));
228	}
229	
230	/**
231	 * 해당 달/난이도의 보상을 이미 수령했는지 localStorage에서 확인
232	 * @returns 수령한 SKOR 양 (없으면 null)
233	 */
234	export function getCachedClaimAmount(yearMonth: string, difficulty: string): number | null {
235	  const cache = _loadClaimedCache();
236	  const key = `${yearMonth}_${difficulty}`;
237	  return key in cache ? cache[key] : null;
238	}
239	
240	/**
241	 * 직전 달 시즌 보상 수령
242	 */
243	export async function claimSeasonReward(difficulty: Difficulty): Promise<ClaimRewardResponse> {
244	  const { data, error } = await supabase.functions.invoke('claim-season-reward', {
245	    body: { difficulty },
246	  });
247	
248	  if (error) {
249	    throw new Error(error.message || 'Failed to claim reward');
250	  }
251	
252	  const result = data as ClaimRewardResponse;
253	
254	  // 수령 성공(또는 이미 수령) 시 localStorage 캐시 갱신
255	  if (result.success && result.skorAwarded && result.skorAwarded > 0) {
