import { type Difficulty } from '../types/GameMode';
import { getCurrentUserId } from './auth';
import { supabase } from './supabase';
import { getCurrentYearMonth } from './localStorage';

export interface LeaderboardEntry {
  userId: string;
  userName: string;
  score: number;
  rank: number;
  characterType?: string;
}

export interface SubmitScoreResponse {
  success: boolean;
  isNewRecord: boolean;
  previousScore: number | null;
  newScore: number;
  rank: number | null;
  message?: string;
}

export interface PrevSeasonReward {
  yearMonth: string;       // 'YYYY-MM' (직전 달)
  rank: number | null;     // null이면 해당 달 기록 없음
  skorAwarded: number;     // 0이면 100위 밖
  alreadyClaimed: boolean;
}

export interface LeaderboardResponse {
  success: boolean;
  difficulty: string;
  yearMonth: string;       // 현재 시즌 'YYYY-MM'
  season: number;          // 시즌 번호
  leaderboard: LeaderboardEntry[];
  currentUserRank: {
    rank: number;
    score: number;
  } | null;
  totalEntries: number;
  prevSeasonReward: PrevSeasonReward | null;
}

export interface ClaimRewardResponse {
  success: boolean;
  alreadyClaimed: boolean;
  rank: number | null;
  skorAwarded: number;
  newBalance?: number;
}

/**
 * 사용자 ID 조회 (Supabase Auth 기반)
 */
export async function getUserId(): Promise<string> {
  return getCurrentUserId();
}

/**
 * 사용자 이니셜 조회
 */
export function getUserInitials(): string | null {
  return localStorage.getItem('userInitials');
}

/**
 * 사용자 이니셜 저장
 * @param initials 3자리 영어 대문자 (예: "ABC")
 */
export function setUserInitials(initials: string): boolean {
  const validation = /^[A-Z]{3}$/;
  if (!validation.test(initials)) {
    return false;
  }

  localStorage.setItem('userInitials', initials);
  return true;
}

/**
 * 이니셜이 설정되어 있는지 확인
 */
export function hasUserInitials(): boolean {
  const initials = getUserInitials();
  return initials !== null && /^[A-Z]{3}$/.test(initials);
}

export interface ScoreVerificationData {
  gameStartTime: number;
  gameEndTime: number;
  goldCollected: number;
  diamondCollected: number;
  topazCollected: number;
  rainbowCollected: number;
  collectBonusTotal?: number; // ability.onCollectSpecial + synergy.collectBonus 누계
  abilityBonusTotal?: number; // addAbilityBonus() + getTickScore 배율 초과분 누계 (레거시 불태우기, 아카이브 배율 등)
}

/**
 * 게임 세션 시작 — 서버가 start_time을 기록하여 점수 조작 방지
 */
export async function startGameSession(difficulty: Difficulty): Promise<string | null> {
  try {
    const { data, error } = await supabase.functions.invoke('game-start', {
      body: { difficulty },
    });
    if (error || !data?.sessionId) return null;
    return data.sessionId as string;
  } catch {
    return null;
  }
}

/**
 * 점수 제출
 */
export async function submitScore(
  score: number,
  difficulty: Difficulty,
  initials: string,
  verificationData: ScoreVerificationData,
  characterType: string = 'chibi',
  sessionId: string | null = null
): Promise<SubmitScoreResponse> {
  if (!/^[A-Z]{3}$/.test(initials)) {
    throw new Error('Invalid initials: must be 3 uppercase letters');
  }

  const { data, error } = await supabase.functions.invoke('leaderboard-submit', {
    body: {
      score,
      difficulty,
      userName: initials,
      sessionId,
      verification: verificationData,
      characterType,
    },
  });

  if (error) {
    throw new Error(error.message || 'Failed to submit score');
  }

  return data as SubmitScoreResponse;
}

/**
 * 리더보드 조회
 */
export async function getLeaderboard(
  difficulty: Difficulty,
  limit: number = 100,
  characterType?: string
): Promise<LeaderboardResponse> {
  const body: Record<string, unknown> = { difficulty, limit };
  if (characterType) body.characterType = characterType;

  const { data, error } = await supabase.functions.invoke('leaderboard-top', {
    body,
  });

  if (error) {
    throw new Error(error.message || 'Failed to fetch leaderboard');
  }

  return data as LeaderboardResponse;
}

// ── 시즌 보상 수령 캐시 (localStorage) ──────────────────────────────────
// 수령 완료된 시즌/난이도는 localStorage에 캐시해 불필요한 서버 조회 방지
// 보안: djb2 서명으로 변조 방지 (실제 이중 수령은 서버 UNIQUE 제약이 방어)

const _CLAIMS_KEY = 'seasonRewardClaims';
const _CLAIMS_SIG_KEY = 'seasonRewardClaimsSig';
const _CLAIMS_SALT = 'ddong-reward-\u0076\u0031';

function _djb2(str: string): string {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) + h) ^ str.charCodeAt(i);
    h = h >>> 0;
  }
  return h.toString(36);
}

function _signClaims(claims: Record<string, number>): string {
  const str = Object.entries(claims)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `${k}:${v}`)
    .join(',') + _CLAIMS_SALT;
  return _djb2(str);
}

/** 현재 달 + 직전 달 외의 오래된 캐시 항목 제거 */
function _pruneOldClaims(claims: Record<string, number>): Record<string, number> {
  const now = new Date();
  const cur = getCurrentYearMonth();
  const prevDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
  const prev = `${prevDate.getUTCFullYear()}-${String(prevDate.getUTCMonth() + 1).padStart(2, '0')}`;
  const keep = new Set([cur, prev]);
  return Object.fromEntries(
    Object.entries(claims).filter(([k]) => keep.has(k.slice(0, 7)))
  );
}

function _loadClaimedCache(): Record<string, number> {
  try {
    const raw = localStorage.getItem(_CLAIMS_KEY);
    const sig = localStorage.getItem(_CLAIMS_SIG_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, number>;
    if (sig && sig !== _signClaims(parsed)) {
      // 서명 불일치 → 변조로 판단, 초기화
      localStorage.removeItem(_CLAIMS_KEY);
      localStorage.removeItem(_CLAIMS_SIG_KEY);
      return {};
    }
    return parsed;
  } catch {
    return {};
  }
}

function _saveClaimedCache(claims: Record<string, number>): void {
  const pruned = _pruneOldClaims(claims);
  localStorage.setItem(_CLAIMS_KEY, JSON.stringify(pruned));
  localStorage.setItem(_CLAIMS_SIG_KEY, _signClaims(pruned));
}

/**
 * 해당 달/난이도의 보상을 이미 수령했는지 localStorage에서 확인
 * @returns 수령한 SKOR 양 (없으면 null)
 */
export function getCachedClaimAmount(yearMonth: string, difficulty: string): number | null {
  const cache = _loadClaimedCache();
  const key = `${yearMonth}_${difficulty}`;
  return key in cache ? cache[key] : null;
}

// ── 캐릭터별 보상 캐시 (localStorage) ────────────────────────────────────

const _CHAR_CLAIMS_KEY = 'charRewardClaims';
const _CHAR_CLAIMS_SIG_KEY = 'charRewardClaimsSig';
const _CHAR_CLAIMS_SALT = 'ddong-char-reward-v1';

function _signCharClaims(claims: Record<string, number>): string {
  const str = Object.entries(claims)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `${k}:${v}`)
    .join(',') + _CHAR_CLAIMS_SALT;
  return _djb2(str);
}

function _loadCharClaimedCache(): Record<string, number> {
  try {
    const raw = localStorage.getItem(_CHAR_CLAIMS_KEY);
    const sig = localStorage.getItem(_CHAR_CLAIMS_SIG_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw) as Record<string, number>;
    if (sig && sig !== _signCharClaims(parsed)) {
      localStorage.removeItem(_CHAR_CLAIMS_KEY);
      localStorage.removeItem(_CHAR_CLAIMS_SIG_KEY);
      return {};
    }
    return parsed;
  } catch {
    return {};
  }
}

function _saveCharClaimedCache(claims: Record<string, number>): void {
  const now = new Date();
  const cur = getCurrentYearMonth();
  const prevDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
  const prev = `${prevDate.getUTCFullYear()}-${String(prevDate.getUTCMonth() + 1).padStart(2, '0')}`;
  const keep = new Set([cur, prev]);
  const pruned = Object.fromEntries(
    Object.entries(claims).filter(([k]) => keep.has(k.slice(0, 7)))
  );
  localStorage.setItem(_CHAR_CLAIMS_KEY, JSON.stringify(pruned));
  localStorage.setItem(_CHAR_CLAIMS_SIG_KEY, _signCharClaims(pruned));
}

/**
 * 해당 달/캐릭터의 보상을 이미 수령했는지 localStorage에서 확인
 * @returns 수령한 SKOR 양 (없으면 null)
 */
export function getCachedCharClaimAmount(yearMonth: string, charId: string): number | null {
  const cache = _loadCharClaimedCache();
  const key = `${yearMonth}_${charId}`;
  return key in cache ? cache[key] : null;
}

/**
 * 직전 달 캐릭터별 보상 수령
 */
export async function claimCharacterReward(characterType: string): Promise<ClaimRewardResponse> {
  const { data, error } = await supabase.functions.invoke('claim-season-reward', {
    body: { characterType },
  });

  if (error) {
    throw new Error(error.message || 'Failed to claim character reward');
  }

  const result = data as ClaimRewardResponse;

  if (result.success && result.skorAwarded && result.skorAwarded > 0) {
    const now = new Date();
    const prevDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
    const prevYearMonth = `${prevDate.getUTCFullYear()}-${String(prevDate.getUTCMonth() + 1).padStart(2, '0')}`;
    const cache = _loadCharClaimedCache();
    cache[`${prevYearMonth}_${characterType}`] = result.skorAwarded;
    _saveCharClaimedCache(cache);
  }

  return result;
}

/**
 * 직전 달 시즌 보상 수령
 */
export async function claimSeasonReward(difficulty: Difficulty): Promise<ClaimRewardResponse> {
  const { data, error } = await supabase.functions.invoke('claim-season-reward', {
    body: { difficulty },
  });

  if (error) {
    throw new Error(error.message || 'Failed to claim reward');
  }

  const result = data as ClaimRewardResponse;

  // 수령 성공(또는 이미 수령) 시 localStorage 캐시 갱신
  if (result.success && result.skorAwarded && result.skorAwarded > 0) {
    const now = new Date();
    const prevDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));
    const prevYearMonth = `${prevDate.getUTCFullYear()}-${String(prevDate.getUTCMonth() + 1).padStart(2, '0')}`;
    const cache = _loadClaimedCache();
    cache[`${prevYearMonth}_${difficulty}`] = result.skorAwarded;
    _saveClaimedCache(cache);
  }

  return result;
}

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

/** 난이도별 시즌 보상 티어 (퍼센타일 기반) */
const REWARD_TIERS = {
  normal:   { r1: 6000,  r2: 4000,  r3: 2000,  top10: 1000, top50: 600,  rest: 200 },
  hard:     { r1: 12000, r2: 8000,  r3: 4000,  top10: 2000, top50: 1200, rest: 400 },
  extreme:  { r1: 30000, r2: 20000, r3: 10000, top10: 5000, top50: 3000, rest: 1000 },
  physical: { r1: 30000, r2: 20000, r3: 10000, top10: 5000, top50: 3000, rest: 1000 },
} as const;

type RewardDifficulty = keyof typeof REWARD_TIERS;

function getReward(difficulty: string, rank: number, totalPlayers: number): number {
  const tier = REWARD_TIERS[difficulty as RewardDifficulty];
  if (!tier) return 0;
  if (rank === 1) return tier.r1;
  if (rank === 2) return tier.r2;
  if (rank === 3) return tier.r3;
  const percentile = rank / totalPlayers;
  if (percentile <= 0.10) return tier.top10;
  if (percentile <= 0.50) return tier.top50;
  return tier.rest;
}

/** 현재 달 'YYYY-MM' 반환 (UTC 기준) */
function getCurrentYearMonth(): string {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = String(now.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

/** 직전 달 'YYYY-MM' 반환 */
function getPrevYearMonth(current: string): string {
  const [y, m] = current.split('-').map(Number) as [number, number];
  const prev = new Date(Date.UTC(y, m - 2, 1));
  return `${prev.getUTCFullYear()}-${String(prev.getUTCMonth() + 1).padStart(2, '0')}`;
}

/** user_skor 잔액 + 주간 집계 업데이트 (캐릭터/난이도 보상 공통) */
async function updateUserSkor(
  // deno-lint-ignore no-explicit-any
  supabaseAdmin: any,
  userId: string,
  reward: number
): Promise<number> {
  const { data: existingSkor } = await supabaseAdmin
    .from('user_skor')
    .select('balance, weekly_earned, week_start')
    .eq('user_id', userId)
    .single();

  const newBalance = Math.floor((existingSkor?.balance ?? 0) + reward);
  const now = new Date();
  const dayOfWeek = now.getUTCDay();
  const daysFromMonday = (dayOfWeek + 6) % 7;
  const weekStart = new Date(Date.UTC(
    now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - daysFromMonday
  ));
  const weekStartStr = weekStart.toISOString().slice(0, 10);
  const isSameWeek = existingSkor?.week_start === weekStartStr;
  const newWeeklyEarned = isSameWeek
    ? Math.floor((existingSkor?.weekly_earned ?? 0) + reward)
    : Math.floor(reward);

  await supabaseAdmin.from('user_skor').upsert({
    user_id: userId,
    balance: newBalance,
    weekly_earned: newWeeklyEarned,
    week_start: weekStartStr,
    updated_at: new Date().toISOString(),
  }, { onConflict: 'user_id' });

  return newBalance;
}

const CHAR_REWARDS: Record<number, number> = { 1: 5000, 2: 3000, 3: 1500 };

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { difficulty, characterType } = await req.json();

    // JWT 인증 (공통)
    const authHeader = req.headers.get('Authorization');
    if (!authHeader) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseUser = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_ANON_KEY') ?? '',
      { global: { headers: { Authorization: authHeader } } }
    );
    const { data: { user }, error: authError } = await supabaseUser.auth.getUser();
    if (authError || !user) {
      return new Response(
        JSON.stringify({ error: 'Unauthorized' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    const currentYearMonth = getCurrentYearMonth();
    const prevYearMonth = getPrevYearMonth(currentYearMonth);

    // ── 캐릭터별 보상 수령 ─────────────────────────────────────────────────
    if (characterType) {
      const { data: existingCharReward } = await supabaseAdmin
        .from('season_reward_history_char')
        .select('skor_awarded, rank')
        .eq('year_month', prevYearMonth)
        .eq('user_id', user.id)
        .eq('character_type', characterType)
        .single();

      if (existingCharReward) {
        return new Response(
          JSON.stringify({
            success: true, alreadyClaimed: true,
            rank: existingCharReward.rank, skorAwarded: existingCharReward.skor_awarded,
          }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      const { data: userPrevEntry } = await supabaseAdmin
        .from('leaderboard_extreme_char')
        .select('score')
        .eq('user_id', user.id).eq('year_month', prevYearMonth)
        .eq('character_type', characterType).single();

      if (!userPrevEntry) {
        return new Response(
          JSON.stringify({ success: true, alreadyClaimed: false, rank: null, skorAwarded: 0 }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      const { count: above } = await supabaseAdmin
        .from('leaderboard_extreme_char')
        .select('*', { count: 'exact', head: true })
        .eq('year_month', prevYearMonth).eq('character_type', characterType)
        .gt('score', userPrevEntry.score);

      const rank = (above ?? 0) + 1;
      const reward = CHAR_REWARDS[rank] ?? 0;

      if (reward === 0) {
        return new Response(
          JSON.stringify({ success: true, alreadyClaimed: false, rank, skorAwarded: 0 }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      const { error: charHistoryError } = await supabaseAdmin
        .from('season_reward_history_char')
        .insert({ year_month: prevYearMonth, user_id: user.id, character_type: characterType, rank, skor_awarded: reward });

      if (charHistoryError) {
        if (charHistoryError.code === '23505') {
          return new Response(
            JSON.stringify({ success: true, alreadyClaimed: true, rank, skorAwarded: reward }),
            { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
          );
        }
        return new Response(
          JSON.stringify({ error: 'Failed to record reward' }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      const newBalance = await updateUserSkor(supabaseAdmin, user.id, reward);
      return new Response(
        JSON.stringify({ success: true, alreadyClaimed: false, rank, skorAwarded: reward, newBalance }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }
    // ── 기존 난이도별 보상 수령 ──────────────────────────────────────────────

    const validDifficulties = ['normal', 'hard', 'extreme', 'physical'];
    if (!validDifficulties.includes(difficulty)) {
      return new Response(
        JSON.stringify({ error: 'Invalid difficulty' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 보상 수령 기간 검증: 직전 달 기록만 수령 가능
    // (새 달이 되면 이전 이전 달은 자동으로 접근 불가)
    // 클라이언트가 임의의 year_month를 body에 넣어 오래된 달 청구 시도를 차단하기 위해
    // 서버에서 항상 현재 기준 직전 달로 고정

    // 이미 수령했는지 확인
    const { data: existingReward } = await supabaseAdmin
      .from('season_reward_history')
      .select('skor_awarded, rank')
      .eq('year_month', prevYearMonth)
      .eq('user_id', user.id)
      .eq('difficulty', difficulty)
      .single();

    if (existingReward) {
      return new Response(
        JSON.stringify({
          success: true,
          alreadyClaimed: true,
          rank: existingReward.rank,
          skorAwarded: existingReward.skor_awarded,
        }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 직전 달 리더보드에서 유저 점수 조회
    const { data: userPrevEntry } = await supabaseAdmin
      .from('leaderboard')
      .select('score')
      .eq('difficulty', difficulty)
      .eq('year_month', prevYearMonth)
      .eq('user_id', user.id)
      .single();

    if (!userPrevEntry) {
      // 해당 달에 기록 없음
      return new Response(
        JSON.stringify({ success: true, alreadyClaimed: false, rank: null, skorAwarded: 0 }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // DB COUNT로 순위 계산 (전체 행 조회 불필요)
    const [{ count: higherCount }, { count: totalPlayers }] = await Promise.all([
      supabaseAdmin.from('leaderboard').select('*', { count: 'exact', head: true })
        .eq('difficulty', difficulty).eq('year_month', prevYearMonth).gt('score', userPrevEntry.score),
      supabaseAdmin.from('leaderboard').select('*', { count: 'exact', head: true })
        .eq('difficulty', difficulty).eq('year_month', prevYearMonth),
    ]);

    const rank = (higherCount ?? 0) + 1;
    const reward = getReward(difficulty, rank, totalPlayers ?? 0);

    // 보상 이력 INSERT (UNIQUE 제약으로 race condition 방지)
    const { error: historyError } = await supabaseAdmin
      .from('season_reward_history')
      .insert({
        year_month: prevYearMonth,
        user_id: user.id,
        difficulty: difficulty,
        rank,
        skor_awarded: reward,
      });

    if (historyError) {
      if (historyError.code === '23505') {
        // 동시 요청으로 이미 INSERT됨 → alreadyClaimed 처리
        return new Response(
          JSON.stringify({ success: true, alreadyClaimed: true, rank, skorAwarded: reward }),
          { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }
      console.error('History insert error:', historyError);
      return new Response(
        JSON.stringify({ error: 'Failed to record reward' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const newBalance = await updateUserSkor(supabaseAdmin, user.id, reward);

    return new Response(
      JSON.stringify({
        success: true,
        alreadyClaimed: false,
        rank,
        skorAwarded: reward,
        newBalance,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

import { createClient } from 'https://esm.sh/@supabase/supabase-js@2';

/** 현재 달 'YYYY-MM' 반환 (UTC 기준) */
function getCurrentYearMonth(): string {
  const now = new Date();
  const y = now.getUTCFullYear();
  const m = String(now.getUTCMonth() + 1).padStart(2, '0');
  return `${y}-${m}`;
}

/** 직전 달 'YYYY-MM' 반환 */
function getPrevYearMonth(current: string): string {
  const [y, m] = current.split('-').map(Number) as [number, number];
  const prev = new Date(Date.UTC(y, m - 2, 1));
  return `${prev.getUTCFullYear()}-${String(prev.getUTCMonth() + 1).padStart(2, '0')}`;
}

/** 시즌 번호: 2026-01 = 1, 2026-02 = 2, ... */
function calcSeason(yearMonth: string): number {
  const [y, m] = yearMonth.split('-').map(Number) as [number, number];
  return (y - 2026) * 12 + m;
}

/** 난이도별 시즌 보상 티어 (퍼센타일 기반) */
const REWARD_TIERS = {
  normal:   { r1: 6000,  r2: 4000,  r3: 2000,  top10: 1000, top50: 600,  rest: 200 },
  hard:     { r1: 12000, r2: 8000,  r3: 4000,  top10: 2000, top50: 1200, rest: 400 },
  extreme:  { r1: 30000, r2: 20000, r3: 10000, top10: 5000, top50: 3000, rest: 1000 },
  physical: { r1: 30000, r2: 20000, r3: 10000, top10: 5000, top50: 3000, rest: 1000 },
} as const;

type RewardDifficulty = keyof typeof REWARD_TIERS;

function getReward(difficulty: string, rank: number, totalPlayers: number): number {
  const tier = REWARD_TIERS[difficulty as RewardDifficulty];
  if (!tier) return 0;
  if (rank === 1) return tier.r1;
  if (rank === 2) return tier.r2;
  if (rank === 3) return tier.r3;
  const percentile = rank / totalPlayers;
  if (percentile <= 0.10) return tier.top10;
  if (percentile <= 0.50) return tier.top50;
  return tier.rest;
}

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

Deno.serve(async (req: Request) => {
  // CORS preflight
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const { difficulty, limit: limitParam, characterType } = await req.json().catch(() => ({}));
    const limit = parseInt(limitParam ?? '100', 10);

    // 입력 검증
    const validDifficulties = ['easy', 'normal', 'hard', 'extreme', 'physical'];
    if (!difficulty || !validDifficulties.includes(difficulty)) {
      return new Response(
        JSON.stringify({ error: 'Invalid difficulty' }),
        { status: 400, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const safeLimit = Math.min(Math.max(1, limit), 100);

    // JWT에서 사용자 인증 (선택적 — 비로그인 시에도 랭킹 조회 가능)
    const authHeader = req.headers.get('Authorization');
    let currentUserId: string | null = null;

    if (authHeader) {
      const supabaseUser = createClient(
        Deno.env.get('SUPABASE_URL') ?? '',
        Deno.env.get('SUPABASE_ANON_KEY') ?? '',
        { global: { headers: { Authorization: authHeader } } }
      );
      const { data: { user } } = await supabaseUser.auth.getUser();
      currentUserId = user?.id ?? null;
    }

    // Service Role 클라이언트 (profiles JOIN을 위해)
    const supabaseAdmin = createClient(
      Deno.env.get('SUPABASE_URL') ?? '',
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? ''
    );

    const yearMonth = getCurrentYearMonth();
    const prevYearMonth = getPrevYearMonth(yearMonth);

    // EXTREME 캐릭터 필터: leaderboard_extreme_char 테이블 조회 후 조기 반환
    if (characterType && difficulty === 'extreme') {
      const { data: charData, error: charError } = await supabaseAdmin
        .from('leaderboard_extreme_char')
        .select('user_id, score, character_type, profiles!inner(initials)')
        .eq('year_month', yearMonth)
        .eq('character_type', characterType)
        .order('score', { ascending: false })
        .limit(safeLimit);

      if (charError) {
        console.error('Extreme char leaderboard error:', charError);
        return new Response(
          JSON.stringify({ error: 'Failed to fetch character leaderboard' }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      const charEntries = (charData ?? []).map((entry, index) => ({
        userId: entry.user_id,
        userName: (entry.profiles as { initials: string | null }).initials ?? '???',
        score: entry.score,
        rank: index + 1,
        characterType: (entry as Record<string, unknown>).character_type ?? 'chibi',
      }));

      // 인증된 유저의 직전 달 캐릭터 보드 rank + 보상 상태 계산
      let charCurrentUserRank: { rank: number; score: number } | null = null;
      let charPrevSeasonReward: {
        yearMonth: string; rank: number | null; skorAwarded: number; alreadyClaimed: boolean;
      } | null = null;

      if (currentUserId) {
        const [userPrevResult, claimResult] = await Promise.all([
          supabaseAdmin.from('leaderboard_extreme_char').select('score')
            .eq('user_id', currentUserId).eq('year_month', prevYearMonth)
            .eq('character_type', characterType).single(),
          supabaseAdmin.from('season_reward_history_char').select('id')
            .eq('user_id', currentUserId).eq('year_month', prevYearMonth)
            .eq('character_type', characterType).single(),
        ]);

        const userPrevEntry = userPrevResult.data;
        if (userPrevEntry) {
          const { count: above } = await supabaseAdmin
            .from('leaderboard_extreme_char')
            .select('*', { count: 'exact', head: true })
            .eq('year_month', prevYearMonth).eq('character_type', characterType)
            .gt('score', userPrevEntry.score);

          const rank = (above ?? 0) + 1;
          const CHAR_REWARDS: Record<number, number> = { 1: 5000, 2: 3000, 3: 1500 };
          charCurrentUserRank = { rank, score: userPrevEntry.score };
          charPrevSeasonReward = {
            yearMonth: prevYearMonth,
            rank,
            skorAwarded: CHAR_REWARDS[rank] ?? 0,
            alreadyClaimed: !!claimResult.data,
          };
        }
      }

      return new Response(
        JSON.stringify({
          success: true,
          difficulty,
          yearMonth,
          season: calcSeason(yearMonth),
          leaderboard: charEntries,
          currentUserRank: charCurrentUserRank,
          totalEntries: charEntries.length,
          prevSeasonReward: charPrevSeasonReward,
        }),
        { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 현재 시즌 리더보드 조회 (profiles와 JOIN하여 이니셜 포함)
    const { data: leaderboard, error: leaderboardError } = await supabaseAdmin
      .from('leaderboard')
      .select(`
        user_id,
        score,
        character_type,
        profiles!inner(initials)
      `)
      .eq('difficulty', difficulty)
      .eq('year_month', yearMonth)
      .order('score', { ascending: false })
      .limit(safeLimit);

    if (leaderboardError) {
      console.error('Leaderboard query error:', leaderboardError);
      return new Response(
        JSON.stringify({ error: 'Failed to fetch leaderboard' }),
        { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    // 응답 형식 변환
    const entries = (leaderboard ?? []).map((entry, index) => ({
      userId: entry.user_id,
      userName: (entry.profiles as { initials: string | null }).initials ?? '???',
      score: entry.score,
      rank: index + 1,
      characterType: (entry as Record<string, unknown>).character_type ?? 'chibi',
    }));

    const totalEntries = entries.length;

    // 현재 유저의 이번 시즌 순위 조회
    let currentUserRank: { rank: number; score: number } | null = null;
    // 직전 시즌 보상 상태 (로그인 유저에게만 제공)
    let prevSeasonReward: {
      yearMonth: string;
      rank: number | null;
      skorAwarded: number;
      alreadyClaimed: boolean;
    } | null = null;

    if (currentUserId) {
      // currentUserRank 조회와 prevSeason 보상 조회는 독립적이므로 병렬 실행
      const [userEntryResult, claimedResult, userPrevEntryResult] = await Promise.all([
        // 이번 시즌 점수
        supabaseAdmin.from('leaderboard').select('score')
          .eq('user_id', currentUserId).eq('difficulty', difficulty).eq('year_month', yearMonth).single(),
        // 직전 시즌 수령 이력 (easy 제외)
        difficulty !== 'easy'
          ? supabaseAdmin.from('season_reward_history').select('skor_awarded, rank')
              .eq('year_month', prevYearMonth).eq('user_id', currentUserId).eq('difficulty', difficulty).single()
          : Promise.resolve({ data: null, error: null }),
        // 직전 시즌 유저 점수 (easy 제외, 미수령 시 순위 계산용)
        difficulty !== 'easy'
          ? supabaseAdmin.from('leaderboard').select('score')
              .eq('user_id', currentUserId).eq('difficulty', difficulty).eq('year_month', prevYearMonth).single()
          : Promise.resolve({ data: null, error: null }),
      ]);

      // 이번 시즌 순위
      const userEntry = userEntryResult.data;
      if (userEntry) {
        const { count: higherCount } = await supabaseAdmin
          .from('leaderboard')
          .select('*', { count: 'exact', head: true })
          .eq('difficulty', difficulty)
          .eq('year_month', yearMonth)
          .gt('score', userEntry.score);

        currentUserRank = { rank: (higherCount ?? 0) + 1, score: userEntry.score };
      }

      // 직전 시즌 보상 상태
      if (difficulty !== 'easy') {
        const claimed = claimedResult.data;
        if (claimed) {
          prevSeasonReward = {
            yearMonth: prevYearMonth,
            rank: claimed.rank,
            skorAwarded: claimed.skor_awarded,
            alreadyClaimed: true,
          };
        } else {
          const userPrevEntry = userPrevEntryResult.data;
          if (userPrevEntry) {
            // DB COUNT로 직전 시즌 순위 계산
            const [{ count: prevHigherCount }, { count: prevTotal }] = await Promise.all([
              supabaseAdmin.from('leaderboard').select('*', { count: 'exact', head: true })
                .eq('difficulty', difficulty).eq('year_month', prevYearMonth).gt('score', userPrevEntry.score),
              supabaseAdmin.from('leaderboard').select('*', { count: 'exact', head: true })
                .eq('difficulty', difficulty).eq('year_month', prevYearMonth),
            ]);
            const rank = (prevHigherCount ?? 0) + 1;
            prevSeasonReward = {
              yearMonth: prevYearMonth,
              rank,
              skorAwarded: getReward(difficulty, rank, prevTotal ?? 0),
              alreadyClaimed: false,
            };
          }
        }
      }
    }

    return new Response(
      JSON.stringify({
        success: true,
        difficulty,
        yearMonth,
        season: calcSeason(yearMonth),
        leaderboard: entries,
        currentUserRank,
        totalEntries,
        prevSeasonReward,
      }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Unexpected error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

